from pathlib import Path
import json,textwrap
A=Path('audit_work');d=json.loads((A/'review_data.json').read_text(encoding='utf-8'));old=json.loads((A/'ea_diagrams.json').read_text(encoding='utf-8'))
V=json.loads((A/'detailed_views.json').read_text(encoding='utf-8'))
def box(id,name,kind,x,y,w=300,h=90,notes='',state='Existente'):
 return dict(id=id,name=name,kind=kind,x=x,y=y,w=w,h=h,notes=notes,state=state,attributes=[],methods=[])
def edge(a,b,name='',typ='Dependency',**kw):return dict(a=a,b=b,name=name,type=typ,**kw)
# Arquitectura objetivo cubre funcionalidades actuales y futuras con estado explícito.
V.append(dict(key='componentes',title='Arquitectura lógica objetivo del WMS completo',type='Component',nodes=[box('web','Panel web\nFilament y Livewire','Component',40,40,320,95),box('mobile','Cliente móvil PWA propuesto\nCámara · IndexedDB · sincronización','Component',40,300,320,110,state='Propuesto'),box('app','Servicios de aplicación\nIAM · Catálogo · Ubicaciones\nProveedores · Operaciones · Inventario','Component',480,130,390,130),box('ports','Dominio y puertos\nRepositorios · transacciones · eventos','Component',1010,130,350,110),box('infra','Adaptadores PostgreSQL y auditoría\nLedger inmutable · saldos · reportes','Component',1010,390,350,110),box('target','Servicios por completar\nCarga inicial · conciliación nocturna\nAlertas externas · copias y restauración','Component',480,430,390,130,state='Propuesto')],edges=[edge('web','app','casos de uso y consultas'),edge('mobile','app','HTTPS propuesto'),edge('app','ports','contratos'),edge('infra','ports','implementa','Realisation'),edge('target','ports','contratos objetivo'),edge('target','infra','persistencia y mensajería')],layout=False))
V.append(dict(key='despliegue',title='Despliegue objetivo y canales del sistema completo',type='Deployment',nodes=[box('desktop','PC cliente\nNavegador y panel administrativo','Node',40,40,300,100),box('phone','Celular HTTPS propuesto\nCámara y cliente PWA\nIndexedDB con pendientes locales','Node',40,350,300,130,state='Propuesto'),box('caddy','Servidor Docker · caddy\nEntrada HTTP 80 / HTTPS 443','Node',470,40,320,100),box('appserver','Servidor Docker · app\nPHP 8.4 · FrankenPHP · Octane\nLaravel y módulos del WMS','Node',920,40,340,130),box('db','Servidor Docker · db\nPostgreSQL 17\nwms y wms_test separados','Node',920,360,340,130),box('async','worker y scheduler\nMisma imagen de aplicación\nCola y tareas programadas','Node',470,360,320,130),box('external','Canales externos propuestos\nSMTP / API correo\nAPI WhatsApp','Node',40,690,300,130,state='Propuesto'),box('backup','Destino de respaldo externo\nCopia cifrada y restauración probada','Node',470,690,320,120,state='Propuesto'),box('tools','Herramientas temporales y CI\nPest · PCOV · Pint · PHPStan\nDeptrac · Infection · JMeter · ZAP','Node',920,690,340,140)],edges=[edge('desktop','caddy','HTTPS 443','Association'),edge('phone','caddy','HTTPS 443 · propuesto','Association'),edge('caddy','appserver','HTTP interno 8000','Association'),edge('appserver','db','SQL 5432 · wms_app','Association'),edge('async','db','cola y tareas · SQL 5432','Association'),edge('async','external','SMTP / HTTPS · propuesto','Association'),edge('async','backup','salida cifrada · propuesto','Association'),edge('tools','db','SQL 5432 · wms_test','Association')],layout=False))
# Ocho vistas de casos de uso cubren las 63 historias; los controles técnicos son requisitos.
groups=[('cu_seguridad','Acceso usuarios y auditoría',range(1,8)),('cu_catalogo','Catálogo identificación y políticas',range(8,17)),('cu_inventario','Inventario ubicaciones y proveedores',list(range(17,24))+list(range(40,44))),('cu_operaciones','Recepciones transferencias y ajustes',range(24,32)),('cu_conteos_pos','Conteos e importación de ventas',range(32,40)),('cu_reportes','Alertas reposición y reportes',range(44,52)),('cu_movil_carga','Carga inicial y operación móvil',range(52,57)),('cu_calidad','Calidad publicación y continuidad',range(57,64))]
bs={s['number']:s for s in d['stories']}
for key,title,nums in groups:
 nums=list(nums);nodes=[];links=[];h=100+((len(nums)+1)//2)*135
 nodes.append(box('boundary','CITY OFERTAS WMS · diseño objetivo'if key!='cu_calidad'else'Proceso de ingeniería y operación del WMS','Boundary',200,20,840,h))
 actors={}
 for i,n in enumerate(nums):
  s=bs[n];role='Equipo de desarrollo y QA'if n>=57 else 'Administrador'if n in [1,4,5,7,53]else'Usuario autenticado'if n in [2,3,6]else'Compras'if n in [42,43,44,45,47,49]else'Supervisor'if n in [8,9,10,11,12,15,16,22,23,30,31,32,34,35,36,37,38,39,40,41,52]else'Almacenero'if n in [13,14,24,25,26,27,28,29,33,54,55,56]else'Gerencia y Contabilidad'
  role=role if n not in [17,18,19,20,21] else 'Servicio de inventario'
  if role not in actors:actors[role]=[]
  actors[role].append(n)
  name=s['id']+'\n'+'\n'.join(textwrap.wrap(s['want'],31))
  kind='Requirement'if n in [17,18,19,20,21,57,58]else'UseCase'
  nodes.append(box(s['id'],name,kind,250+(i%2)*390,75+(i//2)*135,320,95,notes=f"Como {s['role']}, deseo {s['want']}, para {s['why']}. Criterios: "+', '.join(c['id']for c in d['criteria']if c['story']==s['id'])+'. Estado técnico actual: '+s['technical']+'. El diagrama representa el alcance objetivo.'))
 for j,(role,ns)in enumerate(actors.items()):
  rid='actor'+str(j);x=25 if j%2==0 else 1100;y=60+(j//2)*240
  nodes.append(box(rid,role,'Actor',x,y,135,140))
  for n in ns:links.append(edge(rid,bs[n]['id'],'','Association'))
 V.append(dict(key=key,title='Casos de uso objetivo de '+title.lower(),type='Use Case',nodes=nodes,edges=links,layout=False))
# Estados con guardas y acciones comprobables.
V.append(dict(key='estados_conteo',title='Ciclo de conteo y reglas de cierre',type='Statechart',nodes=[box('counting','COUNTING\nCongelar ubicaciones y fijar esperado','State',40,70,320,100),box('review','REVIEW\nMarcar diferencias para reconteo','State',480,70,320,100),box('closed','CLOSED\nAplicar ajustes y liberar ubicaciones','State',920,70,330,100),box('cancelled','CANCELLED\nLiberar sin registrar ajustes','State',480,420,320,100),box('constraints','Condiciones de transición\nToda línea debe tener valor contado\nCero contado difiere de no contado\nCierre sin reconteos pendientes\nOtra persona cierra si contó diferencias\nFallo de ajuste revierte todo el cierre','Note',920,350,360,230)],edges=[edge('counting','review','[todas contadas] enviar','StateFlow'),edge('review','closed','[sin reconteos y segregación] cerrar','StateFlow'),edge('counting','cancelled','anular','StateFlow'),edge('review','cancelled','anular','StateFlow')],layout=False))
# Vistas físicas completas por área, con tipos, PK, FK y nulabilidad.
schema=json.loads((A/'er_model_data.json').read_text(encoding='utf-8'));types=json.loads((A/'db_types.json').read_text(encoding='utf-8'));typ={(c['table_name'],c['column_name']):c['full_type']for c in types};emap={x['name']:x for x in schema['entities']}
areas=[('er_catalogo','Catálogo y códigos',['categories','brands','units','products','product_units','product_barcodes']),('er_ubicaciones','Almacenes ubicaciones y políticas',['warehouses','locations','stock_balances','product_locations','product_stock_policies']),('er_proveedores','Proveedores y abastecimiento',['suppliers','product_suppliers','products']),('er_recepciones','Recepciones y documentos de proveedor',['purchase_receipts','purchase_receipt_items','suppliers']),('er_operaciones','Transferencias y ajustes',['transfer_orders','transfer_order_items','stock_adjustment_requests','movement_reasons']),('er_conteos','Conteos y alcance de ubicaciones',['stock_counts','stock_count_lines','stock_count_locations','locations']),('er_ledger','Ledger y saldos de inventario',['stock_movements','stock_balances','products','movement_reasons']),('er_seguridad','Usuarios roles y permisos',['users','roles','permissions','model_has_roles','model_has_permissions','role_has_permissions']),('er_control','Auditoría importaciones y alertas',['audit_logs','import_jobs','alerts','settings']),('er_soporte','Soporte y persistencia operativa',['document_counters','sku_counters','stock_daily_snapshots','stock_daily_snapshots_default','activity_log','sessions']),('er_infraestructura','Infraestructura de colas y caché',['jobs','job_batches','failed_jobs','cache','cache_locks','password_reset_tokens','migrations'])]
for key,title,names in areas:
 nodes=[]
 for i,name in enumerate(names):
  table=emap[name];attrs=[]
  for c in table['columns']:
   refs=[r for r in schema['relations']if r['table_name']==name and r['column_name']==c['column_name']];tags=('PK 'if c['primary']else'')+('FK 'if refs else'')+('NN'if c['is_nullable']=='NO'else'NULL')
   attrs.append(dict(name=c['column_name'],type=typ[(name,c['column_name'])],visibility='Public',tags=tags,notes=tags+'; '+ '; '.join('REFERENCES '+r['referenced_table']+'.'+r['referenced_column']for r in refs)))
  nodes.append(dict(id='DB.'+name,name=name,kind='Class',x=40+(i%3)*470,y=40+(i//3)*500,w=390,h=52+len(attrs)*18,attributes=attrs,methods=[],stereotype='table',notes='Tabla física existente de PostgreSQL 17. Campos PK y FK y nulabilidad se conservan en estereotipos y notas de cada atributo. Modelo base para el alcance objetivo.',state='Existente'))
 edges=[]
 for r in schema['relations']:
  if r['table_name']in names and r['referenced_table']in names:
   col=next(c for c in emap[r['table_name']]['columns']if c['column_name']==r['column_name']);edges.append(edge('DB.'+r['table_name'],'DB.'+r['referenced_table'],r['column_name'],'Association',childCard='0..*',parentCard='1'if col['is_nullable']=='NO'else'0..1'))
 V.append(dict(key=key,title='Modelo de datos de '+title.lower(),type='Class',nodes=nodes,edges=edges,layout=True))
A.joinpath('target_views.json').write_text(json.dumps(V,ensure_ascii=False,indent=2),encoding='utf-8');print('Vistas detalladas del sistema objetivo',len(V),'historias cubiertas',sum(len(list(g[2]))for g in groups))
